# Program A2 for #1159: cap-C sets in PG(2,q) = development of a Singer difference set D (lines D + j, j in Z_N),
# searched as unions of orbits of a group G generated by x -> x + s (s = N/d) and, optionally, x -> q x (using the
# translate of D fixed by the multiplier q; q^3 = 1 mod N). G permutes lines, so one constraint per line orbit.
# Every witness is re-checked against ALL N lines. Usage: orbit1159.py C p^h [d1 d2 ...]   (d = 1: no translations)
import sys, json, time
sys.path.insert(0, __file__.rsplit('/', 1)[0])
from singer import singer
from ortools.sat.python import cp_model
C = int(sys.argv[1]); spec = sys.argv[2]
p, h = map(int, spec.split('^')) if '^' in spec else (int(spec), 1)
q, N, D = singer(p, h)
# translate D to be fixed by the multiplier q
Dset = set(D); Dm = None
for t in range(N):
    T = {(x + t) % N for x in D}
    if {(q * x) % N for x in T} == T: Dm = sorted(T); break
divs = [int(a) for a in sys.argv[3:]] or [d for d in range(N, 0, -1) if N % d == 0]
for use_mult in (True, False):
    if use_mult and Dm is None: continue
    DD = Dm if use_mult else D
    for d in divs:
        if N % d: continue
        s = N // d
        orb = {}; reps = []
        for x in range(N):
            if x in orb: continue
            stack = [x]; o = []
            while stack:
                y = stack.pop()
                if y in orb: continue
                orb[y] = len(reps); o.append(y)
                stack.append((y + s) % N)
                if use_mult: stack.append((q * y) % N)
            reps.append(o)
        nv = len(reps)
        lines_rep = {}
        for j in range(N):
            key = orb[j]  # line D + j is mapped by G like the point j (G fixes DD as a set)
            if key not in lines_rep: lines_rep[key] = j
        m = cp_model.CpModel(); y = [m.NewBoolVar('y%d' % i) for i in range(nv)]
        for j in lines_rep.values():
            load = sum(y[orb[(x + j) % N]] for x in DD)
            m.Add(load >= 1); m.Add(load <= C)
        sv = cp_model.CpSolver(); sv.parameters.num_workers = 1; sv.parameters.max_time_in_seconds = 300
        t0 = time.time(); st = sv.Solve(m)
        res = sv.StatusName(st)
        print('q=%d N=%d mult=%s d=%d orbits=%d line-orbits=%d C=%d -> %s (%.1fs)' % (q, N, use_mult, d, nv, len(lines_rep), C, res, time.time() - t0), flush=True)
        if st in (cp_model.OPTIMAL, cp_model.FEASIBLE):
            S = sorted(x for x in range(N) if sv.Value(y[orb[x]]))
            loads = [sum(1 for x in DD if (x + j) % N in set(S)) for j in range(N)]
            assert min(loads) >= 1 and max(loads) <= C
            json.dump({'q': q, 'N': N, 'D': DD, 'C': C, 'S': S, 'mult': use_mult, 'd': d}, open('results/singer_q%d_C%d.json' % (q, C), 'w'))
            print('  WITNESS q=%d size=%d loads in [%d,%d]' % (q, len(S), min(loads), max(loads)), flush=True)
            sys.exit(0)
print('no witness found for q=%d C=%d' % (q, C))
